const fs = require('fs');

const PREFS_FILE = '/home/node/.n8n/preferences.json';
const HISTORY_FILE = '/home/node/.n8n/newsletters.json';

function loadJSON(filePath, defaultData) {
  try {
    if (fs.existsSync(filePath)) return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch(e) {}
  return defaultData;
}

function saveJSON(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
}

function parseRSS(xmlText) {
  const items = [];
  const itemRegex = /<item>([^]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xmlText)) !== null) {
    const itemXml = match[1];
    const title = (itemXml.match(/<title[^>]*>([^]*?)<\/title>/i) || [,''])[1].replace(/<\/?[^>]+(>|$)/g, '').trim();
    const link = (itemXml.match(/<link[^>]*>([^]*?)<\/link>/i) || [,''])[1].trim();
    const desc = (itemXml.match(/<description[^>]*>([^]*?)<\/description>/i) || [,''])[1].replace(/<\/?[^>]+(>|$)/g, '').trim();
    if (title && link) items.push({ title, link, description: desc.slice(0, 300), source: 'Google News' });
  }
  return items;
}

function buildHTML(articles, unsubUrl) {
  const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  let itemsHtml = '';
  for (let i = 0; i < articles.length; i++) {
    const a = articles[i];
    itemsHtml += `<div style="margin-bottom:20px;padding:15px;border-left:4px solid #1d4ed8;background:#f8fafc;border-radius:4px;">
      <h3 style="margin:0 0 4px;font-size:16px;"><a href="${a.link}" target="_blank" style="color:#1d4ed8;text-decoration:none;">${i+1}. ${a.title}</a></h3>
      ${a.source ? `<small style="color:#94a3b8;">${a.source}</small>` : ''}
      ${a.description ? `<p style="margin:8px 0 0;color:#475569;font-size:14px;line-height:1.5;">${a.description}</p>` : ''}
    </div>`;
  }
  return `<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"></head><body style="margin:0;padding:20px;background:#f1f5f9;font-family:-apple-system,Segoe UI,Arial,sans-serif;">
    <div style="max-width:600px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;">
      <div style="background:#1d4ed8;padding:20px 30px;">
        <h1 style="margin:0;color:#fff;font-size:22px;">Persona</h1>
        <p style="margin:5px 0 0;color:#dbeafe;font-size:13px;">Votre actualité du ${date}</p>
      </div>
      <div style="padding:30px;">${itemsHtml}</div>
      <div style="padding:16px 30px;background:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;font-size:12px;color:#94a3b8;">
        Vous recevez cet email suite à votre inscription sur Persona.<br>
        <a href="${unsubUrl}" style="color:#dc2626;">Se désinscrire</a>
      </div>
    </div></body></html>`;
}

const prefs = loadJSON(PREFS_FILE, { preferences: [] });
const history = loadJSON(HISTORY_FILE, { newsletters: [] });
const activeUsers = prefs.preferences.filter(p => p.active !== false);
if (activeUsers.length === 0) return [];

const outputItems = [];
for (const user of activeUsers) {
  const tz = user.timezone || 'Africa/Porto-Novo';
  let currentHour;
  try { currentHour = Number(new Intl.DateTimeFormat('en-US', { hour: 'numeric', hour12: false, timeZone: tz }).format(new Date())); }
  catch(e) { currentHour = new Date().getHours(); }
  if (currentHour === 24) currentHour = 0;
  const userHour = parseInt(user.scheduleTime || '08', 10);
  if (userHour !== currentHour) continue;
  const interests = user.topics || [];
  if (interests.length === 0 || !user.email) continue;

  const userHistory = history.newsletters.find(n => n.userId === user.userId);
  const sentUrls = new Set(userHistory ? userHistory.articles.map(a => a.url) : []);
  const today = new Date().toISOString().slice(0, 10);
  if (userHistory && userHistory.sentDate === today) continue;

  const rssUrls = interests.slice(0, 4).map(i =>
    'https://news.google.com/rss/search?q=' + encodeURIComponent(i) + '&hl=fr&gl=FR&ceid=FR:fr'
  );
  const results = await Promise.all(rssUrls.map(async url => {
    try {
      const res = await fetch(url, { signal: AbortSignal.timeout(10000) });
      return parseRSS(await res.text());
    } catch(e) { return []; }
  }));
  const allArticles = results.flat();
  const matched = allArticles.filter(a => {
    if (sentUrls.has(a.link)) return false;
    const text = (a.title + ' ' + a.description).toLowerCase();
    return interests.some(t => text.includes(t.toLowerCase()));
  });
  const selected = matched.slice(0, user.articleCount || 5);
  if (selected.length === 0) continue;

  outputItems.push({
    json: {
      email: user.email,
      subject: 'Persona — Votre édition du ' + today,
      htmlBody: buildHTML(selected, 'http://localhost:5678/webhook/unsubscribe?userId=' + user.userId)
    }
  });

  const entry = { userId: user.userId, sentDate: today, articles: selected.map(a => ({ url: a.link, title: a.title, source: a.source })) };
  if (userHistory) {
    userHistory.sentDate = today;
    userHistory.articles.push(...entry.articles);
    if (userHistory.articles.length > 200) userHistory.articles = userHistory.articles.slice(-200);
  } else {
    history.newsletters.push(entry);
  }
}
saveJSON(HISTORY_FILE, history);
return outputItems;
